insert into public.game_content (game_id, language, volume, level, content, is_published)
values
(
  'stories',
  'en',
  1,
  4,
  $stories_en_level_4$
  [
    {"title":"The Abandoned Lighthouse","story":"In a coastal village, there was a lighthouse that had been dark for years. One stormy night, a fishing boat lost its way and almost approached the rocks. Clara, who knew the lighthouse stories, convinced her father to climb the tower. Using an old lamp and a mirror, they sent flashes toward the sea. The boat recognized the signal and moved away from the dangerous coast. The next day, the villagers decided to restore the lighthouse.","question":"Why did the villagers decide to restore the lighthouse?","correct":"They understood it could help protect boats","options":["They wanted to turn it into a house","They understood it could help protect boats","They only wanted to attract tourists","Because Clara wanted to live there"],"emoji":"🗼"},
    {"title":"The Lost Notebook","story":"For weeks, Julian wrote his invention ideas in a blue notebook. One day, he could not find it and thought someone had taken it. He searched his backpack, desk, and library, but it was nowhere to be found. When he returned home, he saw his little sister drawing on some pages. They were pages from his notebook, which she had found on the sofa and used because she thought they were blank. Julian was upset at first, but then decided to explain why they were important.","question":"What caused the misunderstanding between Julian and his sister?","correct":"She thought the pages were blank","options":["Julian had lost his drawings","She thought the pages were blank","His sister wanted to steal the invention","The notebook was in the library"],"emoji":"📘"},
    {"title":"The City Without Clocks","story":"In a city, everyone depended on clocks to organize their day. One morning, a power failure stopped all the digital clocks, and many people arrived late to their activities. However, a group of older neighbors still used the Sun's position, market sounds, and neighborhood routines to guide themselves. They helped everyone organize their day while the problem was being fixed. In the end, several residents discovered that observing their surroundings could also help them measure time.","question":"What did the residents discover?","correct":"They could find their way by observing signs in their surroundings","options":["Clocks are never necessary","They could find their way by observing signs in their surroundings","Electricity should be eliminated","The market should close early"],"emoji":"🕰️"},
    {"title":"Martina's Promise","story":"Martina promised to take care of her school's garden during the holidays. Before leaving, she prepared a watering calendar and asked her classmates for help. However, a week later, she discovered that some plants were withering. The calendar showed the days, but no one had considered that the weather was hotter than usual. Martina decided to change the watering times and add some shade. The plants began to recover.","question":"What was the main mistake in Martina's original plan?","correct":"She did not consider the weather conditions","options":["She planted too many flowers","She did not consider the weather conditions","She forgot to prepare a calendar","She did not ask her classmates for help"],"emoji":"🌱"},
    {"title":"The Music of the Windows","story":"People living in one building had very different schedules. Some worked at night, while others started early. Noise and arguments became more frequent. One day, a girl named Eva suggested placing small plants on the balconies and organizing a monthly music afternoon. Her idea helped the neighbors get to know each other and discuss their needs. Little by little, they found agreements that made living together more peaceful.","question":"Why did Eva's idea improve the way the neighbors lived together?","correct":"It created opportunities to meet and talk","options":["It removed all the noise","It created opportunities to meet and talk","Everyone changed their schedules","It banned listening to music"],"emoji":"🎵"}
  ]
  $stories_en_level_4$::jsonb,
  true
),
(
  'stories',
  'es',
  1,
  4,
  $stories_es_level_4$
  [
    {"title":"El faro abandonado","story":"En un pueblo costero había un faro que llevaba años apagado. Una noche de tormenta, un barco pesquero perdió el rumbo y estuvo a punto de acercarse demasiado a las rocas. Clara, que conocía las historias del faro, convenció a su padre para subir hasta la torre. Con una vieja lámpara y un espejo, lograron enviar destellos hacia el mar. El barco reconoció la señal y pudo alejarse de la costa peligrosa. Al día siguiente, los vecinos decidieron restaurar el faro.","question":"¿Por qué los vecinos decidieron restaurar el faro?","correct":"Comprendieron que podía ayudar a proteger a los barcos","options":["Querían convertirlo en una casa","Comprendieron que podía ayudar a proteger a los barcos","Querían atraer turistas solamente","Porque Clara quería vivir allí"],"emoji":"🗼"},
    {"title":"El cuaderno perdido","story":"Durante semanas, Julián escribió sus ideas para un invento en un cuaderno azul. Un día no pudo encontrarlo y pensó que alguien lo había tomado. Revisó su mochila, su escritorio y la biblioteca, pero no apareció. Al regresar a casa, vio a su hermana pequeña dibujando en unas hojas. Eran las páginas de su cuaderno, que ella había encontrado en el sofá y usado porque pensó que estaban en blanco. Julián se enojó al principio, pero después decidió explicarle por qué eran importantes.","question":"¿Qué provocó el malentendido entre Julián y su hermana?","correct":"Ella creyó que las hojas estaban en blanco","options":["Julián había perdido sus dibujos","Ella creyó que las hojas estaban en blanco","Su hermana quería robar el invento","El cuaderno estaba en la biblioteca"],"emoji":"📘"},
    {"title":"La ciudad sin relojes","story":"En una ciudad todos dependían de sus relojes para organizar el día. Una mañana, una falla eléctrica detuvo los relojes digitales y muchos llegaron tarde a sus actividades. Sin embargo, un grupo de vecinos mayores seguía guiándose por la posición del Sol, los sonidos del mercado y las rutinas del barrio. Ayudaron a los demás a organizarse mientras se solucionaba el problema. Al final, varios habitantes descubrieron que observar el entorno también podía ser útil para medir el tiempo.","question":"¿Qué enseñanza descubrieron los habitantes?","correct":"Que podían orientarse observando señales de su entorno","options":["Que los relojes nunca son necesarios","Que podían orientarse observando señales de su entorno","Que la electricidad debía eliminarse","Que el mercado debía cerrar temprano"],"emoji":"🕰️"},
    {"title":"La promesa de Martina","story":"Martina prometió cuidar el huerto de su escuela durante las vacaciones. Antes de irse, preparó un calendario de riego y pidió ayuda a sus compañeros. Sin embargo, una semana después descubrió que algunas plantas estaban marchitas. El calendario indicaba los días, pero nadie había tenido en cuenta que el calor era más intenso de lo habitual. Martina decidió cambiar los horarios de riego y colocar una protección para dar sombra. Las plantas comenzaron a recuperarse.","question":"¿Cuál fue el error principal en el plan inicial de Martina?","correct":"No tuvo en cuenta las condiciones del clima","options":["Plantó demasiadas flores","No tuvo en cuenta las condiciones del clima","Olvidó preparar un calendario","No pidió ayuda a sus compañeros"],"emoji":"🌱"},
    {"title":"La música de las ventanas","story":"En un edificio vivían personas con horarios muy diferentes. Algunos trabajaban de noche y otros comenzaban temprano. Los ruidos y las discusiones eran cada vez más frecuentes. Un día, una niña llamada Eva propuso colocar pequeñas plantas en los balcones y organizar una tarde musical mensual. La idea permitió que los vecinos se conocieran mejor y conversaran sobre sus necesidades. Poco a poco, encontraron acuerdos para convivir con más tranquilidad.","question":"¿Por qué la propuesta de Eva ayudó a mejorar la convivencia?","correct":"Porque creó oportunidades para conocerse y dialogar","options":["Porque eliminó todos los ruidos","Porque creó oportunidades para conocerse y dialogar","Porque todos cambiaron sus horarios","Porque prohibió escuchar música"],"emoji":"🎵"}
  ]
  $stories_es_level_4$::jsonb,
  true
)
on conflict (game_id, language, volume, level) do nothing;
